1	package snapshot
2	
3	import (
4		"bufio"
5		"encoding/binary"
6		"errors"
7		"fmt"
8		"hash/crc32"
9		"io"
10		"os"
11	)
12	
13	// On-disk write-ahead log.
14	//
15	// Every successful Put/Delete (and every successfully acquired Snapshot) is
16	// appended as one framed record and forced to stable storage before the call
17	// reports success, so reopening a directory always replays a prefix of
18	// complete records (never a half-written value) and the cumulative snapshot
19	// count is never reset.
20	//
21	// Frame layout, little-endian:
22	//
23	//	magic    uint32   recordMagic
24	//	op       byte     opPut, opDelete or opMeta
25	//	keyLen   uint32
26	//	valLen   uint32
27	//	key      [keyLen]byte
28	//	value    [valLen]byte (absent for deletes)
29	//	crc      uint32   IEEE CRC-32 of all preceding frame bytes
30	//
31	// An opMeta record carries no key and an 8-byte little-endian value holding
32	// the cumulative number of snapshots handed out so far.
33	const (
34		walName = "wal.log"
35		// compactTmpName holds a freshly built log during compaction; it is
36		// atomically renamed over wal.log and never observed directly. A file by
37		// this name left behind by a crash mid-compaction is stale and removed on
38		// the next open.
39		compactTmpName = "wal.log.compact"
40	
41		recordMagic uint32 = 0x534e4150 // "SNAP"
42		opPut       byte   = 1
43		opDelete    byte   = 2
44		opMeta      byte   = 3
45	
