88	// encodeFrame buffers one framed record. Used for ordinary appends (followed
89	// by a flush and sync) and while building a replacement log from scratch.
90	func (l *walWriter) encodeFrame(op byte, key string, value []byte) error {
91		hdr := make([]byte, frameHeaderSize)
92		binary.LittleEndian.PutUint32(hdr[0:4], recordMagic)
93		hdr[4] = op
94		binary.LittleEndian.PutUint32(hdr[5:9], uint32(len(key)))
95		binary.LittleEndian.PutUint32(hdr[9:13], uint32(len(value)))
