107			if _, err := l.w.Write(value); err != nil {
108				return err
109			}
110			h.Write(value)
111		}
112		var crcb [crcSize]byte
113		binary.LittleEndian.PutUint32(crcb[:], h.Sum32())
114		_, err := l.w.Write(crcb[:])
