154	// removeStaleCompact deletes a replacement log left behind by a compaction
155	// that crashed before its atomic rename. Its absence is not an error.
156	func removeStaleCompact(dir string) error {
157		err := os.Remove(dir + string(os.PathSeparator) + compactTmpName)
158		if err != nil && !errors.Is(err, os.ErrNotExist) {
