165	// the given live values, followed by one meta record with snapshotCount. It
166	// builds the complete replacement in compactTmpName, forces it to stable
167	// storage, then atomically renames it over wal.log and forces the directory.
168	// A crash at any point therefore leaves either the old log or the complete
169	// new log: never a truncated or half-written file. On success it returns a
170	// fresh writer positioned at the end of the new log. If the directory sync
171	// fails the rename has still happened, so a non-nil writer is returned
172	// together with the error: the caller must adopt it rather than keep writing
173	// to the old, now-unlinked file.
174	func compactWAL(dir string, live []kvEntry, snapshotCount uint64) (*walWriter, error) {
175		if err := removeStaleCompact(dir); err != nil {
