180		tmp, err := os.OpenFile(path+compactTmpName, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
181		if err != nil {
182			return nil, err
183		}
184		l := &walWriter{f: tmp, w: bufio.NewWriter(tmp)}
185		for i := range live {
