187			// commits the whole replacement atomically.
188			if err := l.encodeFrame(opPut, live[i].key, live[i].value); err != nil {
189				tmp.Close()
190				os.Remove(path + compactTmpName)
191				return nil, err
192			}
193		}
194		// A zero count needs no record: replay of an absent meta yields 0. This
195		// keeps a trivially empty log empty rather than growing it.
196		if snapshotCount > 0 {
197			var v [metaValueSize]byte
198			binary.LittleEndian.PutUint64(v[:], snapshotCount)
199			if err := l.encodeFrame(opMeta, "", v[:]); err != nil {
200				tmp.Close()
201				os.Remove(path + compactTmpName)
202				return nil, err
203			}
204		}
205		if err := l.w.Flush(); err != nil {
206			tmp.Close()
207			os.Remove(path + compactTmpName)
208			return nil, err
209		}
210		if err := tmp.Sync(); err != nil {
211			tmp.Close()
212			os.Remove(path + compactTmpName)
213			return nil, err
214		}
215		if err := tmp.Close(); err != nil {
216			os.Remove(path + compactTmpName)
217			return nil, err
218		}
219	
220		if err := os.Rename(path+compactTmpName, path+walName); err != nil {
221			os.Remove(path + compactTmpName)
222			return nil, err
223		}
224		// Make the rename durable; otherwise a crash could expose the old log
225		// even though the new one was fully written. The rename itself has
226		// already landed either way, so open and return the new writer so the
227		// caller adopts the now-linked file despite reporting the error.
228		syncErr := syncDirectory(dir)
229		next, openErr := openWALWriter(dir, -1)
230		if openErr != nil {
231			// Join collapses to whichever error is set (or both, if both).
232			return nil, errors.Join(syncErr, openErr)
233		}
234		return next, syncErr
235	}
236	
237	// kvEntry is one live key/value pair included in a compacted log.
238	type kvEntry struct {
239		key   string
240		value []byte
241	}
242	
243	// replayWAL applies every complete, intact record in commit order: kv records
244	// go to fn, meta records update snapshotCount. It returns the number of bytes
245	// occupied by the valid prefix; anything after it is a torn or corrupt tail
246	// discarded on the next open.
