257		r := bufio.NewReader(f)
258		var offset int64
259		var snapshotCount uint64
260		hdr := make([]byte, frameHeaderSize)
261	
262		for {
263			start := offset
264			if _, err := io.ReadFull(r, hdr); err != nil {
265				if errors.Is(err, io.EOF) || errors.Is(err, io.ErrUnexpectedEOF) {
266					return start, snapshotCount, nil // absent/torn tail: valid prefix ends here
267				}
268				return 0, 0, err
269			}
270			offset += frameHeaderSize
271	
272			magic := binary.LittleEndian.Uint32(hdr[0:4])
273			op := hdr[4]
274			keyLen := binary.LittleEndian.Uint32(hdr[5:9])
275			valLen := binary.LittleEndian.Uint32(hdr[9:13])
276			if magic != recordMagic ||
277				(op != opPut && op != opDelete && op != opMeta) ||
278				keyLen > maxRecord || valLen > maxRecord ||
279				(op == opDelete && valLen != 0) ||
280				(op == opMeta && (keyLen != 0 || valLen != metaValueSize)) {
281				return start, snapshotCount, nil // corrupt frame: valid prefix ends here
282			}
283	
284			body := make([]byte, int(keyLen)+int(valLen))
285			if _, err := io.ReadFull(r, body); err != nil {
286				return start, snapshotCount, nil
287			}
288			offset += int64(len(body))
289	
290			var crcb [crcSize]byte
291			if _, err := io.ReadFull(r, crcb[:]); err != nil {
292				return start, snapshotCount, nil
293			}
294			offset += crcSize
295	
296			h := crc32.NewIEEE()
297			h.Write(hdr)
298			h.Write(body)
299			if binary.LittleEndian.Uint32(crcb[:]) != h.Sum32() {
300				return start, snapshotCount, nil
301			}
302	
303			switch op {
304			case opPut:
305				key := string(body[:keyLen])
306				fn(opPut, key, body[keyLen:])
307			case opDelete:
