445			go func(w int) {
446				defer writersWg.Done()
447				key := fmt.Sprintf("k%d", w)
448				for i := 0; i < iterations; i++ {
449					v := bytes.Repeat([]byte{byte('a' + w)}, i+1)
450					if err := s.Put(key, v); err != nil {
451						t.Errorf("put: %v", err)
452						return
453					}
454				}
455			}(w)
456		}
457	
458		stop := make(chan struct{})
459		var readersWg sync.WaitGroup
460		readersWg.Add(1)
461		go func() {
462			defer readersWg.Done()
463			for {
464				select {
465				case <-stop:
466					return
467				default:
468				}
469				snap, err := s.Snapshot()
470				if err != nil {
471					t.Errorf("snapshot: %v", err)
472					return
473				}
474				for w := 0; w < writers; w++ {
475					key := fmt.Sprintf("k%d", w)
476					v, ok := snap.Get(key)
477					if !ok {
478						continue // key may not have been written yet
479					}
480					// Every committed value is a whole, un-torn run of one byte.
481					if !allByte(v, byte('a'+w)) {
482						t.Errorf("torn/aliased value for %s: %q", key, v)
483					}
484					// The fixed view never changes between reads of one snapshot.
485					v2, ok := snap.Get(key)
486					if !ok || !bytes.Equal(v, v2) {
487						t.Errorf("snapshot view changed between reads")
488					}
489				}
490				snap.Close()
491			}
492		}()
493	
494		writersWg.Wait()
495		close(stop)
496		readersWg.Wait()
497	}
498	
499	func allByte(b []byte, c byte) bool {
500		for _, x := range b {
501			if x != c {
502				return false
503			}
504		}
505		return true
506	}
507	
508	func TestDurableWithoutClose(t *testing.T) {
509		dir := tempDir(t)
510	
511		// A store whose handle is abandoned without Close: every successful Put
512		// was already fsynced, so reopening the same directory sees all of it.
513		s1, err := Open(dir)
514		if err != nil {
515			t.Fatal(err)
516		}
517		if err := s1.Put("x", []byte("durable")); err != nil {
518			t.Fatal(err)
519		}
520		if _, err := s1.Snapshot(); err != nil {
521			t.Fatal(err)
522		}
523		if err := s1.Delete("x"); err != nil {
524			t.Fatal(err)
525		}
526		if err := s1.Put("y", []byte("kept")); err != nil {
527			t.Fatal(err)
528		}
529	
530		s2, err := Open(dir) // no Close of s1: simulates a crash/restart
531		if err != nil {
532			t.Fatal(err)
533		}
534		if _, ok, _ := s2.Get("x"); ok {
535			t.Fatal("delete before crash lost")
536		}
537		if got, ok, _ := s2.Get("y"); !ok || string(got) != "kept" {
538			t.Fatalf("put before crash lost: %q %v", got, ok)
539		}
540		if n := s2.Stats().Snapshots; n != 1 {
541			t.Fatalf("snapshot count lost across crash: %d", n)
542		}
543		if err := s2.Close(); err != nil {
544			t.Fatal(err)
545		}
546		if err := s1.Close(); err != nil { // abandoned handle: close still idempotent
547			t.Fatal(err)
548		}
549	}
550	
551	func TestConcurrentSnapshotClose(t *testing.T) {
552		s := openStore(t, tempDir(t))
553		for _, k := range []string{"a", "b", "c"} {
554			if err := s.Put(k, []byte("0")); err != nil {
555				t.Fatal(err)
556			}
557		}
558	
559		const readers = 8
560		var readerWg sync.WaitGroup
561		var sawClosed atomic.Int64
562		for r := 0; r < readers; r++ {
563			readerWg.Add(1)
564			go func() {
565				defer readerWg.Done()
566				for {
567					snap, err := s.Snapshot()
568					if err != nil {
569						if errors.Is(err, fs.ErrClosed) {
570							sawClosed.Add(1)
571							return
572						}
573						t.Errorf("snapshot err: %v", err)
574						return
575					}
576					// The fixed view must be internally consistent: two full
577					// passes over the keys return identical bytes, each value a
578					// well-formed decimal marker.
579					first := map[string][]byte{}
580					for _, k := range []string{"a", "b", "c"} {
581						v, ok := snap.Get(k)
582						if !ok {
583							t.Error("initial key missing in snapshot")
584							break
585						}
586						if n, err := strconv.Atoi(string(v)); err != nil || n < 0 {
587							t.Errorf("malformed value %q", v)
588							break
589						}
590						first[k] = v
591					}
592					for k, want := range first {
593						if got, ok := snap.Get(k); !ok || !bytes.Equal(got, want) {
594							t.Error("snapshot view changed mid-read")
595						}
596					}
597					snap.Close()
598				}
599			}()
600		}
601	
602		var writerWg sync.WaitGroup
603		writerWg.Add(1)
604		go func() {
605			defer writerWg.Done()
606			for i := 1; i <= 500; i++ {
607				if err := s.Put("a", []byte(strconv.Itoa(i))); err != nil {
608					return // store may close under us
609				}
610			}
611		}()
612	
613		writerWg.Wait()
614		if err := s.Close(); err != nil {
615			t.Fatal(err)
616		}
617		readerWg.Wait()
618	
619		if sawClosed.Load() == 0 {
620			t.Fatal("no reader observed fs.ErrClosed after close")
621		}
622	
623		// Snapshots already handed out survive close; verify one explicitly.
624		// (Acquire-then-close ordering.)
625		s2 := openStore(t, tempDir(t))
626		if err := s2.Put("k", []byte("v")); err != nil {
627			t.Fatal(err)
628		}
629		snap, err := s2.Snapshot()
630		if err != nil {
631			t.Fatal(err)
632		}
633		if err := s2.Put("k", []byte("v2")); err != nil {
634			t.Fatal(err)
635		}
636		if err := s2.Close(); err != nil {
637			t.Fatal(err)
638		}
639		if got, ok := snap.Get("k"); !ok || string(got) != "v" {
640			t.Fatalf("snapshot broken by concurrent close: %q %v", got, ok)
641		}
642		if err := snap.Close(); err != nil {
643			t.Fatal(err)
644		}
645	}
646

