package snapshot

import (
	"io/fs"
	"sort"
	"sync"
)

// KVPair is one key/value pair returned by a scan or a cursor page. The
// bytes are owned by the caller.
type KVPair struct {
	Key   string
	Value []byte
}

// ScanRange returns every live key k with start <= k <= end in byte order,
// together with its value from the latest committed view. A reversed range
// (start > end) or a range that matches nothing yields an empty slice and no
// error. Hit semantics match Get: present keys include those carrying an empty
// value; deleted and never-written keys never appear. Scanning a closed store
// returns an error wrapping fs.ErrClosed. The returned bytes are owned by the
// caller and reads are served from the in-memory view.
func (s *Store) ScanRange(start, end string) ([]KVPair, error) {
	if s.closed.Load() {
		return nil, errStoreClosed
	}
	return collectView(*s.current.Load(), start, end), nil
}

// ScanPrefix returns every live key beginning with prefix, in byte order. An
// empty prefix scans the whole view; a prefix that matches nothing yields an
// empty slice and no error. Scanning a closed store returns an error wrapping
// fs.ErrClosed.
func (s *Store) ScanPrefix(prefix string) ([]KVPair, error) {
	if s.closed.Load() {
		return nil, errStoreClosed
	}
	start, end := prefixRange(prefix)
	return collectView(*s.current.Load(), start, end), nil
}

// ScanRange returns the pairs of the snapshot's fixed view with start <= k <=
// end, in byte order. A reversed range or one that matches nothing is empty.
// A closed snapshot scans as an empty result, never an error.
func (s *Snapshot) ScanRange(start, end string) []KVPair {
	v := s.v.Load()
	if v == nil {
		return nil
	}
	return collectView(*v, start, end)
}

// ScanPrefix returns every key of the snapshot's fixed view beginning with
// prefix, in byte order. A closed snapshot scans as an empty result.
func (s *Snapshot) ScanPrefix(prefix string) []KVPair {
	v := s.v.Load()
	if v == nil {
		return nil
	}
	start, end := prefixRange(prefix)
	return collectView(*v, start, end)
}

// Cursor is a paged reader over a fixed view. Opening a cursor pins the view
// at that instant: later writes, deletes, compactions, new snapshots and even
// closing the store never change what its pages return. The versions a cursor
// references stay out of garbage collection until it is closed.
//
// A Cursor is safe for concurrent use; Next and Close calls are serialized,
// with closing queued behind any page already in flight.
type Cursor struct {
	store *Store // nil for snapshot cursors; used to release the pin
	pin   *pin

	mu     sync.Mutex
	view   view   // fixed view; nil after Close
	keys   []string // keys of the fixed view within the scan bounds, in order
	offset int      // index of the next key to return
}

// Cursor opens a paged scan over the latest committed view, locked to the
// view current at the moment of the call. limit<=0 bounds to [start,end].
// Opening a cursor on a closed store returns an error wrapping fs.ErrClosed.
func (s *Store) Cursor(start, end string) (*Cursor, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed.Load() {
		return nil, errStoreClosed
	}
	v := *s.current.Load()
	c := &Cursor{store: s, view: v}
	c.pin = s.pins.add(c, v)
	c.keys = sortedKeysInRange(v, start, end)
	return c, nil
}

// CursorPrefix opens a paged prefix scan over the latest committed view.
func (s *Store) CursorPrefix(prefix string) (*Cursor, error) {
	start, end := prefixRange(prefix)
	return s.Cursor(start, end)
}

// Cursor opens a paged scan over the snapshot's fixed view. The cursor keeps
// serving that view after the snapshot itself is closed. A cursor opened on a
// closed snapshot is immediately exhausted: its first Next returns an empty
// page and ok=false.
func (s *Snapshot) Cursor(start, end string) *Cursor {
	v := s.v.Load()
	c := &Cursor{view: v}
	if v != nil {
		c.keys = sortedKeysInRange(*v, start, end)
	}
	return c
}

// CursorPrefix opens a paged prefix scan over the snapshot's fixed view.
func (s *Snapshot) CursorPrefix(prefix string) *Cursor {
	start, end := prefixRange(prefix)
	return s.Cursor(start, end)
}

// Next returns up to limit consecutive pairs in byte order and advances the
// cursor. An empty page with ok=false marks the end; later calls keep
// returning the end marker. limit must be positive, otherwise Next returns an
// error wrapping fs.ErrInvalid, advances nothing and leaves the cursor usable.
// Reading a closed cursor is an ordinary miss: an empty page, ok=false and no
// error. The returned bytes are owned by the caller; repeated paging of one
// cursor never repeats or loses a key and yields byte-identical values.
func (c *Cursor) Next(limit int) (pairs []KVPair, ok bool, err error) {
	if limit <= 0 {
		return nil, false, errBadLimit
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.view == nil || c.offset >= len(c.keys) {
		return nil, false, nil
	}
	n := len(c.keys) - c.offset
	if n > limit {
		n = limit
	}
	page := make([]KVPair, n)
	for i := 0; i < n; i++ {
		node := c.view[c.keys[c.offset+i]]
		page[i] = KVPair{Key: c.keys[c.offset+i], Value: cloneBytes(node.value)}
	}
	c.offset += n
	return page, true, nil
}

// Close releases the cursor's fixed view. It is idempotent and returns nil;
// closing queues behind a Next already in flight and never interrupts it.
func (c *Cursor) Close() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.view == nil {
		return nil
	}
	c.view = nil
	c.keys = nil
	if c.pin != nil {
		c.store.pins.remove(c.pin)
		c.pin = nil
	}
	return nil
}

// collectView gathers the present pairs of v within [start, end], sorted by
// byte order. A reversed range is an empty result rather than an error.
func collectView(v view, start, end string) []KVPair {
	keys := sortedKeysInRange(v, start, end)
	if len(keys) == 0 {
		return []KVPair{}
	}
	out := make([]KVPair, 0, len(keys))
	for _, k := range keys {
		n := v[k]
		if n == nil || !n.present {
			continue
		}
		out = append(out, KVPair{Key: k, Value: cloneBytes(n.value)})
	}
	return out
}

// sortedKeysInRange returns the present keys k of v with start <= k <= end in
// byte order. Deleted tombstones are skipped, so a reversed interval (or one
// without hits) naturally yields an empty slice.
func sortedKeysInRange(v view, start, end string) []KVPair {
	return nil
}

// prefixRange converts a prefix into the smallest key that carries it and the
// largest key that does. An empty prefix covers the whole key space.
func prefixRange(prefix string) (start, end string) {
	if prefix == "" {
		return "", ""
	}
	b := []byte(prefix)
	for i := len(b) - 1; i >= 0; i-- {
		if b[i] != 0xff {
			return prefix, string(b[:i]) + string(rune(b[i]+1))
		}
	}
	return prefix, "" // all 0xff bytes: every key with the prefix is >= it
}

var _ = sort.Strings // retained for key sorting below
var _ fs.FileMode

