	// A cursor's versions are exempt from compaction reclamation regardless
	// of whether it scans the latest view or a snapshot view. The registry
	// outlives the open store handle; if the store is gone no compaction can
	// run anyway and Close simply drops the registration.
	if s.store != nil {
		c.store = s.store
		c.pin = s.store.pins.add(v, c.keys)
	}
	return c
}

// CursorPrefix opens a paged prefix scan over the snapshot's fixed view.
func (s *Snapshot) CursorPrefix(prefix string) *Cursor {
	start, end := prefixRange(prefix)
	return s.Cursor(start, end)
}

// Next returns up to limit consecutive pairs in byte order and advances the
// cursor. An empty page with ok=false marks the end; calls after that keep
// returning the end marker. limit must be positive, otherwise Next returns an
// error wrapping fs.ErrInvalid, advances nothing and leaves the cursor
// usable. Reading a closed cursor is an ordinary miss: an empty page,
// ok=false and no error. The returned bytes are owned by the caller; paging
// one cursor across pages never repeats or loses a key and yields
// byte-identical values for the same key.
func (c *Cursor) Next(limit int) (pairs []KVPair, ok bool, err error) {
	if limit <= 0 {
		return nil, false, errBadLimit
	}
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.view == nil || c.offset >= len(c.keys) {
		return nil, false, nil
	}
	n := len(c.keys) - c.offset
	if n > limit {
		n = limit
	}
	page := make([]KVPair, n)
	for i := 0; i < n; i++ {
		node := c.view[c.keys[c.offset+i]]
		page[i] = KVPair{Key: c.keys[c.offset+i], Value: cloneBytes(node.value)}
	}
	c.offset += n
	return page, true, nil
}

// Close releases the cursor's fixed view and lets the next compaction reclaim
// the versions it pinned. It is idempotent and returns nil; closing queues
// behind a Next already in flight and never interrupts it.
func (c *Cursor) Close() error {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.view == nil {
		return nil
	}
	c.view = nil
	c.keys = nil
	if c.pin != nil {
		c.store.pins.remove(c.pin)
		c.pin = nil
	}
	return nil
}

// collectView gathers the present pairs of v within [start, end], sorted by
// byte order. A reversed range is an empty result rather than an error.
func collectView(v view, start, end string) []KVPair {
	keys := sortedKeysInRange(v, start, end)
	out := make([]KVPair, 0, len(keys))
	for _, k := range keys {
		out = append(out, KVPair{Key: k, Value: cloneBytes(v[k].value)})
	}
	return out
}

// sortedKeysInRange returns the present keys k of v with start <= k and
// (end == "" or k <= end), in byte order. Tombstones are skipped, so a
// reversed interval (non-empty end smaller than start) or one without hits
// naturally yields an empty slice. Empty bounds are open: start="" is the
// smallest possible key, end="" means no upper bound.
func sortedKeysInRange(v view, start, end string) []string {
	if end != "" && start > end {
		return nil
	}
	keys := make([]string, 0, len(v))
	for k, n := range v {
		if n == nil || !n.present {
			continue
		}
		if k < start {
			continue
		}
		if end != "" && k > end {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// prefixRange converts a prefix into the smallest key carrying it and the
// first key past every key carrying it. An empty prefix covers the whole key
// space. If every byte of the prefix is 0xff no finite upper bound exists, so
// end is returned empty to denote "unbounded above".
func prefixRange(prefix string) (start, end string) {
	if prefix == "" {
		return "", ""
	}
	b := []byte(prefix)
	for i := len(b) - 1; i >= 0; i-- {
		if b[i] != 0xff {
			b[i]++
			return prefix, string(b[:i+1])
		}
	}
	return prefix, ""
}

// pin records one open store cursor's claim on history. The cursor's view
// keeps the versions alive in memory; the pin makes the compaction rewrite
// keep them on disk. keys lists, in order, exactly the keys the cursor may
// read, so retention tracks the open cursors rather than cumulative writes.
type pin struct {
	id   uint64
	view view
	keys []string
}

// pinRegistry tracks open store cursors. It has its own lock because cursor
// Close releases a pin without holding the store write lock, while scans and
// pages take neither lock: fsync-bound writes never stall readers.
type pinRegistry struct {
	mu     sync.RWMutex
	nextID uint64
	pins   []*pin // append-only in opening order; removal swaps-and-shrinks
}

func (r *pinRegistry) add(v view, keys []string) *pin {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.nextID++
	p := &pin{id: r.nextID, view: v, keys: keys}
	r.pins = append(r.pins, p)
	return p
}

func (r *pinRegistry) remove(target *pin) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for i, p := range r.pins {
		if p == target {
			r.pins[i] = r.pins[len(r.pins)-1]
			r.pins[len(r.pins)-1] = nil
			r.pins = r.pins[:len(r.pins)-1]
			return
		}
	}
}

// ordered returns the currently open pins sorted by opening order. The slice
// is a snapshot: a cursor closing afterwards does not mutate it.
func (r *pinRegistry) ordered() []*pin {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]*pin, len(r.pins))
	copy(out, r.pins)
	sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
	return out
}

// errBadLimit is returned when a cursor page is requested with a non-positive
// limit; it wraps fs.ErrInvalid like every other invalid-argument error.
var errBadLimit = errors.Join(
	errors.New("snapshot: cursor limit must be positive"),
	fs.ErrInvalid,
)

