// Cursor opens a paged scan over the snapshot's fixed view. The cursor keeps
// serving that view even after the snapshot itself has been closed. A cursor
// opened from a closed snapshot is immediately exhausted: its first Next
// returns an empty page and ok=false.
func (s *Snapshot) Cursor(start, end string) *Cursor {
	vp := s.v.Load()
	c := &Cursor{}
	if vp == nil {
		return c // cursor on an already closed snapshot: immediately exhausted
	}
	// Serialize pin registration against an in-flight compaction, so a cursor
	// is either fully before one (its versions are retained in the rewrite) or
	// fully after it (its view is one the rewrite already ends in). The store
	// lock is still usable after Store.Close; then no compaction can race.
	locked := false
	if s.store != nil {
		s.store.mu.Lock()
		locked = true
	}
	v := *vp
	c.view = v
	c.keys = sortedKeysInRange(v, start, end)
	// A cursor's versions are exempt from compaction reclamation regardless
	// of whether it scans the latest view or a snapshot view. The registry
	// outlives the open store handle; if the store is gone no compaction can
	// run anyway and Close simply drops the registration.
	if s.store != nil {
		c.store = s.store
		c.pin = s.store.pins.add(v, c.keys)
	}
	if locked {
		s.store.mu.Unlock()
	}
	return c
}

