input.old_string:
// collectView gathers the present pairs of v within [start, end], sorted by
// byte order. A reversed range is an empty result rather than an error.
func collectView(v view, start, end string) []KVPair {
	keys := sortedKeysInRange(v, start, end)
	out := make([]KVPair, 0, len(keys))
	for _, k := range keys {
		out = append(out, KVPair{Key: k, Value: cloneBytes(v[k].value)})
	}
	return out
}

// sortedKeysInRange returns the present keys k of v with start <= k and
// (end == "" or k <= end), in byte order. Tombstones are skipped, so a
// reversed interval (non-empty end smaller than start) or one without hits
// naturally yields an empty slice. Empty bounds are open: start="" is the
// smallest possible key, end="" means no upper bound.
func sortedKeysInRange(v view, start, end string) []string {
	if end != "" && start > end {
		return nil
	}
	keys := make([]string, 0, len(v))
	for k, n := range v {
		if n == nil || !n.present {
			continue
		}
		if k < start {
			continue
		}
		if end != "" && k > end {
			continue
		}
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

