// pin records one open store cursor's claim on history. The cursor's view
// keeps the versions alive in memory; the pin makes the compaction rewrite
// keep them on disk. keys lists, in order, exactly the keys the cursor may
// read, so retention tracks the open cursors rather than cumulative writes.
type pin struct {
	id   uint64
	view view
	keys []string
}

// pinRegistry tracks open store cursors. It has its own lock because cursor
// Close releases a pin without holding the store write lock, while scans and
// pages take neither lock: fsync-bound writes never stall readers.
type pinRegistry struct {
	mu     sync.RWMutex
	nextID uint64
	pins   []*pin // append-only in opening order; removal swaps-and-shrinks
}

func (r *pinRegistry) add(v view, keys []string) *pin {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.nextID++
	p := &pin{id: r.nextID, view: v, keys: keys}
	r.pins = append(r.pins, p)
	return p
}

func (r *pinRegistry) remove(target *pin) {
	r.mu.Lock()
	defer r.mu.Unlock()
	for i, p := range r.pins {
		if p == target {
			r.pins[i] = r.pins[len(r.pins)-1]
			r.pins[len(r.pins)-1] = nil
			r.pins = r.pins[:len(r.pins)-1]
			return
		}
	}
}

