1	package snapshot
2	
3	import (
4		"errors"
5		"io/fs"
6		"sort"
7		"sync"
8	)
9	
10	// KVPair is one key/value pair returned by a scan or a cursor page. The
11	// bytes are owned by the caller.
12	type KVPair struct {
13		Key   string
14		Value []byte
15	}
16	
17	// ScanRange returns every live key k with start <= k <= end in byte order,
18	// together with its value from the latest committed view. An empty start or
19	// end leaves that side unbounded. A reversed range (start > end) or a range
20	// that matches nothing yields an empty slice and no error. Hit semantics
21	// match Get: present keys include those carrying an empty value; deleted and
22	// never-written keys never appear. Scanning a closed store returns an error
23	// wrapping fs.ErrClosed. The returned bytes are owned by the caller and reads
24	// are served straight from the in-memory view, along the same path as
25	// snapshot reads.
26	func (s *Store) ScanRange(start, end string) ([]KVPair, error) {
27		if s.closed.Load() {
28			return nil, errStoreClosed
29		}
30		return collectView(*s.current.Load(), start, end, true), nil
31	}
32	
33	// ScanPrefix returns every live key beginning with prefix, in byte order. An
34	// empty prefix scans the whole view; a prefix that matches nothing yields an
35	// empty slice and no error. Scanning a closed store returns an error
36	// wrapping fs.ErrClosed.
37	func (s *Store) ScanPrefix(prefix string) ([]KVPair, error) {
38		if s.closed.Load() {
39			return nil, errStoreClosed
40		}
41		start, end := prefixRange(prefix)
42		return collectView(*s.current.Load(), start, end, false), nil
43	}
44	
45	// ScanRange returns the pairs of the snapshot's fixed view with start <= k <=
46	// end, in byte order. A reversed range or one that matches nothing is empty.
47	// A closed snapshot scans as an empty result, never an error.
48	func (s *Snapshot) ScanRange(start, end string) []KVPair {
49		v := s.v.Load()
50		if v == nil {
51			return []KVPair{}
52		}
53		return collectView(*v, start, end, true)
54	}
55	
56	// ScanPrefix returns every key of the snapshot's fixed view beginning with
57	// prefix, in byte order. A closed snapshot scans as an empty result.
58	func (s *Snapshot) ScanPrefix(prefix string) []KVPair {
59		v := s.v.Load()
60		if v == nil {
61			return []KVPair{}
62		}
63		start, end := prefixRange(prefix)
64		return collectView(*v, start, end, false)
65	}
66	
67	// Cursor is a paged reader over a fixed view. Opening a cursor pins the view
68	// at that instant: later writes, deletes, compactions, newly opened snapshots
69	// and even closing the store never change what its pages return. The versions
70	// a cursor references are kept out of compaction reclamation until it is
71	// closed; the compaction after close reclaims them.
72	//
73	// A Cursor is safe for concurrent use: Next and Close serialize, with closing
74	// queued behind any page already in flight.
75	type Cursor struct {
76		store *Store // nil for cursors opened from a snapshot
77		pin   *pin   // nil once released, or for snapshot cursors
78	
79		mu     sync.Mutex
80		view   view     // fixed view; nil after Close
81		keys   []string // keys of the fixed view within the scan bounds, in order
82		offset int      // index of the next key to return
83	}
84	
85	// Cursor opens a paged scan over the latest committed view, fixed to the view
86	// current the instant the call begins and bounded to the closed interval
87	// [start, end]. An empty start or end leaves that side unbounded. Opening a
88	// cursor on a closed store returns an error wrapping fs.ErrClosed.
89	func (s *Store) Cursor(start, end string) (*Cursor, error) {
90		return s.openCursor(start, end, true)
91	}
92	
93	// CursorPrefix opens a paged prefix scan over the latest committed view.
94	func (s *Store) CursorPrefix(prefix string) (*Cursor, error) {
95		start, end := prefixRange(prefix)
96		return s.openCursor(start, end, false)
97	}
98	
99	func (s *Store) openCursor(start, end string, endInclusive bool) (*Cursor, error) {
100		s.mu.Lock()
101		if s.closed.Load() {
102			s.mu.Unlock()
103			return nil, errStoreClosed
104		}
105		v := *s.current.Load()
106		// Pin registration inside the write lock is O(1): it only records the
107		// immutable view, its generation and the bounds. The O(n) key filtering
108		// and sort happen after unlocking, so opening a cursor is not held
109		// hostage to a write's fsync, and paging never takes the store lock.
110		p := s.pins.add(s.viewGen, v, start, end, endInclusive)
111		s.mu.Unlock()
112	
113		return &Cursor{store: s, pin: p, view: v, keys: sortedKeysInRange(v, start, end, endInclusive)}, nil
114	}
115	
116	// Cursor opens a paged scan over the snapshot's fixed view, bounded to the
117	// closed interval [start, end]. The cursor keeps serving that view even
118	// after the snapshot itself has been closed. A cursor opened from a closed
119	// snapshot is immediately exhausted: its first Next returns an empty page
120	// and ok=false.
121	func (s *Snapshot) Cursor(start, end string) *Cursor {
122		return s.openCursor(start, end, true)
123	}
124	
125	// CursorPrefix opens a paged prefix scan over the snapshot's fixed view.
126	func (s *Snapshot) CursorPrefix(prefix string) *Cursor {
127		start, end := prefixRange(prefix)
128		return s.openCursor(start, end, false)
129	}
130	
131	func (s *Snapshot) openCursor(start, end string, endInclusive bool) *Cursor {
132		vp := s.v.Load()
133		c := &Cursor{}
134		if vp == nil {
135			return c // cursor on an already closed snapshot: immediately exhausted
136		}
137		// Serialize pin registration against an in-flight compaction, so a cursor
138		// is either fully before one (its versions are retained in the rewrite) or
139		// fully after it (its view is one the rewrite already ends in). The store
140		// lock stays usable after Store.Close; then no compaction can race. The
141		// O(n) key filtering and sort wait until the lock is released.
142		v := *vp
143		var p *pin
144		if s.store != nil {
145			s.store.mu.Lock()
146			p = s.store.pins.add(s.gen, v, start, end, endInclusive)
147			s.store.mu.Unlock()
148		}
149		c.store = s.store
150		c.pin = p
151		c.view = v
152		c.keys = sortedKeysInRange(v, start, end, endInclusive)
153		return c
154	}
155	
156	// Next returns up to limit consecutive pairs in byte order and advances the
157	// cursor. An empty page with ok=false marks the end; calls after that keep
158	// returning the end marker. limit must be positive, otherwise Next returns an
159	// error wrapping fs.ErrInvalid, advances nothing and leaves the cursor
160	// usable. Reading a closed cursor is an ordinary miss: an empty page,
161	// ok=false and no error. The returned bytes are owned by the caller; paging
162	// one cursor across pages never repeats or loses a key and yields
163	// byte-identical values for the same key.
164	func (c *Cursor) Next(limit int) (pairs []KVPair, ok bool, err error) {
165		if limit <= 0 {
166			return nil, false, errBadLimit
167		}
168		c.mu.Lock()
169		defer c.mu.Unlock()
170		if c.view == nil || c.offset >= len(c.keys) {
171			return nil, false, nil
172		}
173		n := len(c.keys) - c.offset
174		if n > limit {
175			n = limit
176		}
177		page := make([]KVPair, n)
178		for i := 0; i < n; i++ {
179			node := c.view[c.keys[c.offset+i]]
180			page[i] = KVPair{Key: c.keys[c.offset+i], Value: cloneBytes(node.value)}
181		}
182		c.offset += n
183		return page, true, nil
184	}
185	
186	// Close releases the cursor's fixed view and lets the next compaction reclaim
187	// the versions it pinned. It is idempotent and returns nil; closing queues
188	// behind a Next already in flight and never interrupts it.
189	func (c *Cursor) Close() error {
190		c.mu.Lock()
191		defer c.mu.Unlock()
192		if c.view == nil {
193			return nil
194		}
195		c.view = nil
196		c.keys = nil
197		if c.pin != nil {
198			c.store.pins.remove(c.pin)
199			c.pin = nil
200		}
201		return nil
202	}
203	
204	// collectView gathers the present pairs of v within the bounds, sorted by
205	// byte order. endInclusive selects [start,end] (range scans) versus
206	// [start,end) (prefix scans, where end is the first key past the prefix).
207	func collectView(v view, start, end string, endInclusive bool) []KVPair {
208		keys := sortedKeysInRange(v, start, end, endInclusive)
209		out := make([]KVPair, 0, len(keys))
210		for _, k := range keys {
211			out = append(out, KVPair{Key: k, Value: cloneBytes(v[k].value)})
212		}
213		return out
214	}
215	
216	// sortedKeysInRange returns the present keys k of v with start <= k and
217	// (end == "" or k < end / k <= end), in byte order. Tombstones are skipped,
218	// so a reversed interval (non-empty end smaller than start) or one without
219	// hits naturally yields an empty slice. Empty bounds are open: start="" is
220	// the smallest possible key, end="" means no upper bound.
221	func sortedKeysInRange(v view, start, end string, endInclusive bool) []string {
222		if end != "" && start > end {
223			return nil
224		}
225		keys := make([]string, 0, len(v))
226		for k, n := range v {
227			if n == nil || !n.present {
228				continue
229			}
230			if k < start {
231				continue
232			}
233			if end != "" {
234				if endInclusive {
235					if k > end {
236						continue
237					}
238				} else if k >= end {
239					continue
240				}
241			}
242			keys = append(keys, k)
243		}
244		sort.Strings(keys)
245		return keys
246	}
247	
248	// prefixRange converts a prefix into the smallest key carrying it and the
249	// first key past every key carrying it. An empty prefix covers the whole key
250	// space. If every byte of the prefix is 0xff no finite upper bound exists, so
251	// end is returned empty to denote "unbounded above".
252	func prefixRange(prefix string) (start, end string) {
253		if prefix == "" {
254			return "", ""
255		}
256		b := []byte(prefix)
257		for i := len(b) - 1; i >= 0; i-- {
258			if b[i] != 0xff {
259				b[i]++
260				return prefix, string(b[:i+1])
261			}
262		}
263		return prefix, ""
264	}
